let literal_hash = "3caad84613ddc9f765de49b027ff80a007269303afe3327a80b3904c44cedd2b"
let transcript calls =
  let pending = ref (Json.array calls) in
  let evaluate ~parent:_ ~until history =
    match !pending with
    | [] -> failwith "Evaluator exceeded independent original transcript"
    | expected::tail ->
        require (same (X.history_json history) (get "history" expected)) "Native enumeration/deletion order changed";
        require (same (N.to_json until) (get "until" expected)) "Explicit numeric horizon changed";
        pending:=tail; E.Check_result.of_json (get "result" expected)
  in evaluate,(fun () -> require (!pending=[]) "Native algorithm omitted original evaluations")
let error code action =
  try ignore(action()); failwith ("Expected "^code) with Diagnostic.Error value -> require (value.code=code) ("Unexpected diagnostic: "^value.code)
let semantic message action =
  try ignore(action()); failwith "Expected semantic rejection" with Diagnostic.Error value -> require (value.message=message) value.message
let run_explore ?limits ?parent raw =
  let evaluate,finish = transcript (get "calls" raw) in
  let result,usage = K.explore_with_usage ?limits ?parent (X.Bounds.of_json (get "config" raw)) ~evaluate in
  finish(); require (same (X.Report.to_json result) (get "expected" raw)) "Complete exploration report changed"; result,usage
let run_reduce raw =
  let evaluate,finish = transcript (get "calls" raw) in
  let result = K.reduce ~history:(X.frames_of_json (get "history" raw)) ~until:(N.of_json (get "until" raw))
      ~signature:(X.Failure_signature.of_json (get "signature" raw)) ~max_evaluations:(integer(get "max_evaluations" raw)) ~evaluate () in
  finish(); require (same (X.Reduction.to_json result) (get "expected" raw)) "Complete reduction or minimality changed"
let () =
  require (Canonical.fingerprint literals=literal_hash) "Independent original literal inventory changed";
  let profile=B.limits_json B.default_limits in
  require (Json.integer(get "max_work" profile)=Z.of_string "8500125714074944" &&
    Z.compare (Json.integer(get "max_work" profile)) (Z.pred(Z.shift_left Z.one 53))<=0)
    "Workflow profile lost its derived exact integer ceiling";
  require (integer(get "max_monitor_items" profile)=8_000_000 && integer(get "max_callback_report_nodes" profile)=500_000)
    "Historical callback or live workspace capacities were narrowed";
  List.iter (fun raw -> ignore(run_explore raw)) (Json.array(get "explores" literals));
  List.iter run_reduce (Json.array(get "reductions" literals));
  List.iter (fun raw ->
