    require (same (Json.Array(List.map X.History_case.to_json actual)) (get "expected" raw)) "Named/seeded/incomplete histories changed")
    (Json.array(get "adversarial" literals));
  let raw = List.hd (Json.array(get "explores" literals)) in
  let _,usage = run_explore raw in
  require (usage.evaluations=9 && usage.work_charged>0 && usage.retained_peak>0) "Missing aggregate accounting";
  ignore(run_explore ~limits:(B.make_limits ~max_work:usage.work_charged ()) raw);
  error "workflow_work_limit" (fun () -> run_explore ~limits:(B.make_limits ~max_work:(usage.work_charged-1) ()) raw);
  let parent = W.create ~profile:"workflow-test" ~error_code:"ancestor_exhausted" ~maximum:usage.work_charged () in
  ignore(run_explore ~parent raw); require (W.remaining parent=0) "Workflow failed to charge every phase to parent";
  let parent = W.create ~profile:"workflow-test" ~error_code:"ancestor_exhausted" ~maximum:(usage.work_charged-1) () in
