  ignore(run_explore ~limits:(B.make_limits ~max_report_bytes:usage.report_bytes ~max_report_nodes:usage.report_nodes ()) raw);
  error "verification_exploration_limit" (fun () -> run_explore ~limits:(B.make_limits ~max_report_bytes:(usage.report_bytes-1) ()) raw);
