  let count=ref 0 in
  let evaluate,finish=transcript (get "calls" raw) in
  let change key value raw=Json.Object((key,value)::List.remove_assoc key(Json.object_fields raw)) in
  semantic "Evaluator changed checked requirement inventory." (fun () -> K.explore config
